#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [AbsorbedDoseOfIonizingRadiation; 17] = [
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Gray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Femtogray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Picogray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Nanogray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Microgray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Milligray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Centigray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Decigray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Kilogray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Megagray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Gigagray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Teragray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Petagray,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Rad,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Millirad,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Kilorad,
        ),
        AbsorbedDoseOfIonizingRadiation::const_new(
            1234.5,
            AbsorbedDoseOfIonizingRadiationUnit::Megarad,
        ),
    ];
    for (q, &unit) in AT_COMPILE_TIME
        .iter()
        .zip(AbsorbedDoseOfIonizingRadiationUnit::ALL)
    {
        assert_eq!(
            q.as_base().to_bits(),
            AbsorbedDoseOfIonizingRadiation::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in AbsorbedDoseOfIonizingRadiationUnit::ALL {
            assert_eq!(
                AbsorbedDoseOfIonizingRadiation::const_new(v, unit)
                    .as_base()
                    .to_bits(),
                AbsorbedDoseOfIonizingRadiation::<f64>::new(v, unit)
                    .as_base()
                    .to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = AbsorbedDoseOfIonizingRadiation::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            AbsorbedDoseOfIonizingRadiation::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in AbsorbedDoseOfIonizingRadiationUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        AbsorbedDoseOfIonizingRadiation::from_base(0.0)
            .auto_unit()
            .unit,
        AbsorbedDoseOfIonizingRadiationUnit::Gray
    );
}

